import json,copy,sqlite3,hashlib,io,xml.etree.ElementTree as E
from PIL import Image
from mermaid_geometry_coverage import check
from playwright.sync_api import sync_playwright
from native_worker import R,W,native,now
script=r'''xml=>{document.body.innerHTML='<div id="g" style="width:8192px;height:8192px;position:relative"></div>';const g=new Graph(document.getElementById('g'));new mxCodec(mxUtils.parseXml(xml)).decode(mxUtils.parseXml(xml).getElementsByTagName('mxGraphModel')[0],g.model);g.view.validate();let results=[];for(const c of Object.values(g.model.cells).filter(c=>c.vertex && g.getCellStyle(c).shadow==='1')){const st=g.view.getState(c);if(!st?.shape?.node || !getComputedStyle(st.shape.node).filter.includes('drop-shadow'))throw Error('native shadow absent from actual renderer '+c.id);} for(const e of Object.values(g.model.cells).filter(c=>c.edge)){for(const source of [true,false]){const t=g.model.getTerminal(e,source);if(!t)throw Error('unbound edge');const state=g.view.getState(e),idx=source?0:state.absolutePoints.length-1,before=state.absolutePoints[idx].clone(),children=(t.children||[]).filter(c=>c.vertex).map(c=>({id:c.id,x:g.view.getState(c)?.x,y:g.view.getState(c)?.y})),old=t.geometry.clone(),moved=old.clone();moved.x+=17;moved.y+=11;g.model.beginUpdate();g.model.setGeometry(t,moved);g.model.endUpdate();g.view.validate();const after=g.view.getState(e).absolutePoints[idx];const edgeState=g.view.getState(e);if(edgeState.style[source?'startArrow':'endArrow']==='classic' && !edgeState.shape.node.querySelector('path'))throw Error('native arrow SVG missing');const childMoves=children.map(c=>({id:c.id,dx:g.view.getState(g.model.cells[c.id]).x-c.x,dy:g.view.getState(g.model.cells[c.id]).y-c.y}));if(childMoves.some(c=>Math.abs(c.dx-17)>.05||Math.abs(c.dy-11)>.05))throw Error('native terminal children did not follow node');results.push({edge:e.id,terminal:t.id,source,dx:after.x-before.x,dy:after.y-before.y,childMoves});g.model.beginUpdate();g.model.setGeometry(t,old);g.model.endUpdate();g.view.validate();}}g.destroy();return results;}'''
base=W/'mermaid_geometry_repair';results=[];db=sqlite3.connect(W/'jobs.sqlite');selected=[json.loads(x[0]) for x in db.execute("select output_record from jobs where id in(select id from mermaid_geometry_repairs where state='published')")]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/home/shaoshitong/.cache/ms-playwright/chromium-1228/chrome-linux64/chrome',args=['--disable-dev-shm-usage']);page=b.new_page();page.route('**/*',lambda r:r.abort());page.set_content('<html></html>');page.evaluate('window.mxLoadResources=false;window.mxLoadStylesheets=false;window.onDrawioViewerLoad=()=>{}');page.add_script_tag(path=str(native.renderer_path(R).parent/'assets/viewer-static.min.js'))
 for r in selected:
  if r.get('error'):continue
  id=r['id'];xml=(R/r['code_file']).read_text();ast=json.loads((R/r['source_ast_file']).read_text());stats=r['svg_conversion'];png=(R/r['image_file']).read_bytes();assert hashlib.sha256(xml.encode()).hexdigest()==r['code_sha256'];assert hashlib.sha256(png).hexdigest()==r['image_sha256'];w,h=Image.open(io.BytesIO(png)).size;fresh=native.native_job(xml,w,h,90,W/'rendering_fonts/remote_render.py',8192,R/'evaluation/assets/drawio-runtime-v32.6.1/manifest.json');assert fresh['ok'] and fresh['png']==png,'Fresh actual drawio PNG mismatch';coverage=check(ast,xml,stats['mermaid_source_metadata']);assert coverage['ok'],coverage;wrong=E.fromstring(xml);edge=next(c for c in wrong.iter('mxCell') if c.get('edge')=='1');edge.set('target',edge.get('source'));assert not check(ast,E.tostring(wrong,encoding='unicode'),stats['mermaid_source_metadata'])['ok'];wrong=E.fromstring(xml);c=next(c for c in wrong.iter('mxCell') if c.get('value'));c.set('value','DELETED LABEL');assert not check(ast,E.tostring(wrong,encoding='unicode'),stats['mermaid_source_metadata'])['ok'];moves=page.evaluate(script,xml);ok=all(abs(m['dx']-17)<.05 and abs(m['dy']-11)<.05 for m in moves);item={'id':id,'ok':ok,'moves':moves,'source_coverage':coverage,'negative_wrong_terminal_and_missing_label':True};results.append(item);print(json.dumps({'id':id,'moves':len(moves),'ok':ok}),flush=True)
 b.close()
(base/'editability_audit.json').write_text(json.dumps({'at':now(),'results':results},indent=2));assert all(x['ok'] for x in results)
